css:
/* Story playback */
.playback { border-bottom: 1px solid var(--rule); padding-bottom: 18px; }
.playback select { font: inherit; font-size:14px; padding:7px 8px; width:100%; min-width:0; border:1px solid var(--rule); border-radius:3px; background:var(--paper); color:var(--ink); }
.playback .ap-label { font-size:12px; color:var(--muted); margin-bottom:-5px; }
.ap-buttons { display:flex; gap:5px; flex-wrap:wrap; }
.ap-buttons button { border:1px solid var(--rule); border-radius:3px; background:var(--paper); padding:7px 9px; min-height:36px; cursor:pointer; font-size:13px; }
.ap-buttons .ap-primary { background:var(--ink); color:var(--paper); border-color:var(--ink); min-width:80px; }
.ap-buttons button:disabled { opacity:.45; cursor:default; }
#ap-progress { width:100%; accent-color:var(--red); margin:2px 0; }
.ap-options { display:flex; flex-wrap:wrap; align-items:center; gap:10px 16px; font-size:13px; }
.ap-options label { display:flex; align-items:center; gap:5px; }
.ap-options select { width:auto; padding:4px; }
.playback input[type=checkbox] { accent-color:var(--red); }
.ap-limit { font-size:12px; color:var(--muted); }
.ap-caption { border-top:1px solid var(--rule); padding-top:10px; font-family:var(--f-text); line-height:1.5; }
.ap-caption p { margin:0 0 8px; }
.ap-caption .ap-title { font-family:var(--f-display); font-size:19px; font-weight:600; line-height:1.15; }
.ap-caption .ap-source { font-family:var(--f-ui); font-size:12px; color:var(--muted); margin-top:9px; }
.ap-caption figure { margin:10px 0 0; padding-left:11px; border-left:2px solid var(--rule); }
.ap-caption blockquote { margin:0; font-size:15px; }
.ap-caption blockquote p { margin:0 0 .5em; }
.ap-caption figcaption { font-family:var(--f-ui); font-size:12px; color:var(--muted); }
.ap-key { font-size:11px; color:var(--muted); margin:0; display:flex; align-items:center; gap:5px; }
.ap-key span { width:8px; height:8px; display:inline-block; border-radius:50%; }
.ap-key-red { background:var(--red); } .ap-key-brown { background:var(--brown); margin-left:10px; }
.ap-method { font-size:12px; line-height:1.4; }
.ap-overlay { pointer-events:none; }
.ap-actor-label { font-family:var(--f-ui); font-size:10px; font-weight:600; paint-order:stroke; stroke:var(--panel); stroke-width:3px; stroke-linejoin:round; fill:var(--ink); }
.ap-actor-body { stroke:var(--panel); stroke-width:1.5px; }
.ap-trace { fill:none; stroke:var(--water); stroke-width:3; vector-effect:non-scaling-stroke; opacity:.8; stroke-linecap:round; }
.ap-position-ring { fill:none; stroke:var(--water); stroke-width:1.4; opacity:.65; }
.ap-map-label { position:absolute; left:10px; bottom:10px; padding:5px 8px; max-width:calc(100% - 20px); background:var(--panel); border:1px solid var(--rule); border-radius:3px; font-size:12px; pointer-events:none; }
@media(max-width:860px) { .ap-buttons button { min-height:40px; } .ap-options { gap:9px; } }
